254: /** Vertical lane: mean of deduped category lane indices (can fall between band lines). */
255: function laneYForCategories(categories: ProjectCategory[]): number {
256:   const indices = Array.from(
257:     new Set(
258:       categories
259:         .map((c) => CATEGORY_TO_LANE[c])
260:         .map((lane) => LANE_ORDER.indexOf(lane))
261:     )
262:   );
263:   if (indices.length === 0) {
264:     return TIMELINE_LANE_TOP;
265:   }
266:   const meanIndex =
267:     indices.reduce((sum, index) => sum + index, 0) / indices.length;
268:   return TIMELINE_LANE_TOP + meanIndex * TIMELINE_LANE_SPACING;
269: }
