272:   const normalized = hex.replace('#', '');
273:   const r = Number.parseInt(normalized.slice(0, 2), 16);
274:   const g = Number.parseInt(normalized.slice(2, 4), 16);
275:   const b = Number.parseInt(normalized.slice(4, 6), 16);
