454:   private wrapTextByWords(text: string, maxCharsPerLine: number, maxLines: number): string[] {
455:     const words = text.split(/\s+/).filter(Boolean);
456:     if (words.length === 0) {
457:       return [''];
458:     }
459:     const lines: string[] = [];
460:     let current = '';
461:     for (const word of words) {
462:       const candidate = current ? `${current} ${word}` : word;
463:       if (candidate.length <= maxCharsPerLine) {
464:         current = candidate;
465:       } else {
466:         lines.push(current || word);
467:         current = current && current !== word ? word : '';
468:       }
469:       if (lines.length === maxLines) {
470:         break;
471:       }
472:     }
473:     if (lines.length < maxLines && current) {
474:       lines.push(current);
475:     }
476:     if (lines.length > maxLines) {
477:       lines.length = maxLines;
478:     }
479:     const usedWords = lines.join(' ').split(/\s+/).filter(Boolean).length;
480:     if (usedWords < words.length && lines.length > 0) {
481:       lines[lines.length - 1] = `${lines[lines.length - 1].replace(/\.\.\.$/, '')}...`;
