const xBrain = this.xForYear((MILESTONE_GOOGLE_BRAIN_START + 2020) / 2);
const xRai = this.xForYear((2020 + MILESTONE_GOOGLE_DROP) / 2);
const xDm = this.xForYear((MILESTONE_GOOGLE_DROP + DATA_MAX_YEAR) / 2);

const wBs = (MILESTONE_BROWN_BS_START + MILESTONE_BROWN_BS_END) / 2;
const wMs = (MILESTONE_BROWN_MS_START + MILESTONE_BROWN_MS_END) / 2;
const wUw = (MILESTONE_UW_START + DATA_MAX_YEAR) / 2;

const xBrown = this.xForYear((MILESTONE_BROWN_BS_START + MILESTONE_BROWN_MS_END) / 2);
