const xGap2 = this.xForYear((MILESTONE_GOOGLE_DROP + MILESTONE_UW_START) / 2);

const addOccupiedLabel = (centerX: number, centerY: number, width: number, height: number) => {
  occupied.push({
    x: centerX - width / 2,
    y: centerY - height / 2,
    width,
    height,
  });
};

